+func decodedUnitLength(s string) int {
+	units := 0
+	for len(s) > 0 {
+		r, size := decodeUnitRune(s)
+		units++
+		if r > 0xffff {
+			units++
+		}
+		s = s[size:]
+	}
+	return units
+}
+
+func TestLengthMatchesDecoding(t *testing.T) {
+	compare := func(s string) {
+		t.Helper()
+		if got, want := Length(s), decodedUnitLength(s); got != want {
+			t.Fatalf("length of %x: got %d, want %d", s, got, want)
+		}
+	}
+	// All short byte pairs include overlong encodings, isolated continuation
+	// bytes and truncated sequences, which must retain their decoder behavior.
+	for first := 0; first < 256; first++ {
+		compare(string([]byte{byte(first)}))
+		for second := 0; second < 256; second++ {
+			compare(string([]byte{byte(first), byte(second)}))
+		}
+	}
+	for _, value := range []string{
+		"\xe0\x9f\xbf", "\xe0\xa0\x80", "\xed\x9f\xbf", "\xed\xa0\x80", "\xed\xbf\xbf",
+		"\xf0\x8f\xbf\xbf", "\xf0\x90\x80\x80", "\xf4\x8f\xbf\xbf", "\xf4\x90\x80\x80", "\xf5\x80\x80\x80",
+	} {
+		compare(value)
+	}
+	random := rand.New(rand.NewSource(1))
+	for i := 0; i < 10000; i++ {
+		bytes := make([]byte, random.Intn(256))
+		_, _ = random.Read(bytes)
+		compare(string(bytes))
+	}
